 * tree. Scalar leaves marked `false` are dropped, and any container (object or
 * array) left without dirty descendants collapses to `undefined`. Array
 * positions are preserved (clean slots become `undefined`) so indices stay
 * meaningful; object keys that become clean are omitted entirely.
 */
function pruneDirtyFields(value: any): any {
  if (Array.isArray(value)) {
    let hasDirty = false;
    const result = value.map((item) => {
      const pruned = pruneDirtyFields(item);
      if (!isUndefined(pruned)) {
        hasDirty = true;
      }
      return pruned;
    });

    return hasDirty ? result : undefined;
  }

  if (isObject(value)) {
    const result: Record<string, any> = {};
    let hasDirty = false;

    for (const key in value) {
      const pruned = pruneDirtyFields(value[key]);
      if (!isUndefined(pruned)) {
        result[key] = pruned;
        hasDirty = true;
      }
    }

    return hasDirty ? result : undefined;
  }

  return value === true ? true : undefined;
